"""Dependency-free HTML renderer for synchronized M5 views."""

from __future__ import annotations

from html import escape


def render_standalone_html(title: str, payload_json: str) -> str:
    safe_payload = payload_json.replace("</", "<\\/")
    return _TEMPLATE.replace("__TITLE__", escape(title)).replace("__PAYLOAD__", safe_payload)


_TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__</title>
<style>
:root{--ink:#17211d;--muted:#617068;--paper:#f3f0e8;--panel:#fffdf7;--line:#d9d4c8;--jade:#0d6b59;--mint:#53b89d;--amber:#d98b31;--red:#b94b45;--blue:#3972a5;--purple:#7a5b9e;--shadow:0 14px 34px #26362c18}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:radial-gradient(circle at 10% 0,#dcece2 0,transparent 32%),var(--paper);font:14px/1.45 ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}.shell{max-width:1500px;margin:auto;padding:28px}.mast{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:20px}.eyebrow{color:var(--jade);font:700 12px/1.2 ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase}h1{font:700 clamp(26px,4vw,46px)/1.05 Georgia,serif;margin:7px 0 5px}.subtitle{color:var(--muted);max-width:720px}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:12px 14px;box-shadow:var(--shadow)}button,select{border:1px solid var(--line);border-radius:9px;background:white;color:var(--ink);padding:8px 11px;font:inherit}button{cursor:pointer}button.primary{background:var(--jade);color:white;border-color:var(--jade)}#time{flex:1;min-width:180px;accent-color:var(--jade)}#clock{font:700 13px ui-monospace,monospace;min-width:105px;text-align:right}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}.stat{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:11px 13px}.stat b{display:block;font:700 18px ui-monospace,monospace}.stat span{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.grid{display:grid;grid-template-columns:minmax(420px,1.05fr) minmax(480px,1.3fr);gap:14px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:16px;box-shadow:var(--shadow);min-width:0}.panel h2{font:700 18px Georgia,serif;margin:0}.panelhead{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px}.hint{color:var(--muted);font-size:12px}.space-wrap{height:440px}.gantt-wrap{height:440px;overflow:auto;border-top:1px solid var(--line)}svg{display:block;width:100%;height:100%}.events{grid-column:1/-1}.event-list{height:290px;overflow:auto;border-top:1px solid var(--line)}.event{display:grid;grid-template-columns:110px 150px 1fr 1.3fr;gap:12px;padding:8px 7px;border-bottom:1px solid #ebe7dd;font-size:12px}.event.active{background:#dcece2;border-left:4px solid var(--jade)}.event .mono{font-family:ui-monospace,monospace}.pill{display:inline-block;padding:2px 7px;border-radius:999px;background:#e8e4da;color:var(--muted)}.legend{display:flex;flex-wrap:wrap;gap:12px;color:var(--muted);font-size:11px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px}.tooltip{position:fixed;pointer-events:none;display:none;max-width:360px;background:#17211ded;color:white;padding:9px 11px;border-radius:9px;font:12px/1.45 ui-monospace,monospace;z-index:9}.empty{color:var(--muted);padding:20px}@media(max-width:980px){.mast{display:block}.controls{margin-top:16px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}.event{grid-template-columns:90px 120px 1fr}}@media(max-width:600px){.shell{padding:14px}.stats{grid-template-columns:repeat(2,1fr)}.space-wrap,.gantt-wrap{height:360px}.event{grid-template-columns:80px 1fr}.event div:nth-child(n+3){display:none}}
</style>
</head>
<body><main class="shell">
<header class="mast"><div><div class="eyebrow">Neutral-atom FTQC · M5</div><h1>__TITLE__</h1><div class="subtitle">One physical timeline, three synchronized views. Routing waits reflect declared corridor conflicts and finite hardware capacity.</div></div><div class="legend"><span><i class="dot" style="background:var(--jade)"></i>transport</span><span><i class="dot" style="background:var(--amber)"></i>control</span><span><i class="dot" style="background:var(--blue)"></i>readout</span><span><i class="dot" style="background:var(--purple)"></i>sync</span></div></header>
<section class="controls" aria-label="Timeline controls"><label>Profile <select id="run"></select></label><button id="back" title="Previous event">◀</button><button id="play" class="primary">Play</button><button id="next" title="Next event">▶</button><input id="time" type="range" min="0" max="1" value="0" step="1" aria-label="Time cursor"><output id="clock">0 ns</output></section>
<section id="stats" class="stats"></section>
<div class="grid"><section class="panel"><div class="panelhead"><h2>Spatial state</h2><span id="space-meta" class="hint"></span></div><div class="space-wrap"><svg id="space" role="img" aria-label="Machine zones and block positions"></svg></div></section>
<section class="panel"><div class="panelhead"><h2>Resource Gantt</h2><span class="hint">cursor shared with all views</span></div><div class="gantt-wrap"><svg id="gantt" role="img" aria-label="Resource schedule"></svg></div></section>
<section class="panel events"><div class="panelhead"><h2>Event stream</h2><span id="event-meta" class="hint"></span></div><div id="events" class="event-list"></div></section></div>
</main><div id="tip" class="tooltip"></div>
<script id="visualization-data" type="application/json">__PAYLOAD__</script>
<script>
const bundle=JSON.parse(document.getElementById('visualization-data').textContent);let run=bundle.runs[0],t=0,playing=false,timer=null;
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',colors={move_atoms:'#0d6b59',move_block:'#0d6b59',align_atoms:'#53b89d',apply_1q_pulse:'#d98b31',apply_2q_rydberg_gate:'#b94b45',image_atoms:'#3972a5',measure_atoms:'#3972a5',reset_atoms:'#9b7844',load_reservoir_atom:'#9b7844',place_atom:'#0d6b59',wait:'#88857e',emit_sync:'#7a5b9e'};
const escHtml=value=>String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function node(tag,attrs={},text=''){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text)n.textContent=text;return n}function fmt(ns){return ns>=1e6?(ns/1e6).toFixed(3)+' ms':ns>=1e3?(ns/1e3).toFixed(1)+' μs':ns+' ns'}
function init(){bundle.runs.forEach((x,i)=>$('run').add(new Option(x.label,i)));$('run').onchange=e=>{run=bundle.runs[+e.target.value];t=0;setup()};$('time').oninput=e=>{t=+e.target.value;render()};$('play').onclick=toggle;$('back').onclick=()=>jump(-1);$('next').onclick=()=>jump(1);setup()}
function setup(){$('time').max=run.makespan_ns;$('time').step=Math.max(1,Math.round(run.makespan_ns/1000));renderStats();render();}
function toggle(){playing=!playing;$('play').textContent=playing?'Pause':'Play';if(playing){timer=setInterval(()=>{t+=Math.max(1,run.makespan_ns/240);if(t>=run.makespan_ns){t=run.makespan_ns;toggle()}$('time').value=Math.round(t);render()},35)}else clearInterval(timer)}
function jump(dir){const points=[...new Set(run.events.map(e=>e.time_ns))].sort((a,b)=>a-b);const i=dir>0?points.findIndex(x=>x>t):points.findLastIndex(x=>x<t);if(i>=0){t=points[i];$('time').value=t;render()}}
function renderStats(){const m=run.metrics,values=[['Makespan',fmt(run.makespan_ns)],['Tasks',m.task_count],['Peak parallel',m.max_parallel_tasks],['Resource wait',fmt(m.total_wait_ns)],['Observations',m.observation_count]];$('stats').innerHTML=values.map(x=>`<div class="stat"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function render(){t=Math.min(t,run.makespan_ns);$('clock').value=fmt(Math.round(t));renderSpace();renderGantt();renderEvents()}
function currentSnapshot(){let s=run.snapshots[0];for(const x of run.snapshots){if(x.time_ns<=t)s=x;else break}return s}
function renderSpace(){const svg=$('space');svg.replaceChildren();svg.setAttribute('viewBox','-20 -20 440 290');const s=currentSnapshot();run.trajectories.forEach(tr=>{const pts=tr.waypoints.map(p=>p.join(',')).join(' ');svg.append(node('polyline',{points:pts,fill:'none',stroke:'#a8b4ac','stroke-width':4,'stroke-dasharray':'7 6','data-tip':tr.trajectory_id+' · conflicts: '+tr.conflict_group_ids.join(', ')}))});run.zones.forEach(z=>{svg.append(node('rect',{x:z.x_um,y:z.y_um,width:z.width_um,height:z.height_um,rx:12,fill:'#f8f6ef',stroke:'#9aa79f','stroke-width':2,'data-tip':`${z.kind} · capacity ${z.capacity} · occupied ${s.zone_occupancy[z.zone_id]||0}`}));svg.append(node('text',{x:z.x_um+10,y:z.y_um+20,fill:'#43524a','font-size':12,'font-weight':700},z.zone_id.toUpperCase()));svg.append(node('text',{x:z.x_um+10,y:z.y_um+38,fill:'#718078','font-size':10},`${s.zone_occupancy[z.zone_id]||0} / ${z.capacity} atoms`))});const entries=Object.entries(s.block_locations);entries.forEach(([block,loc],i)=>{let p=blockPoint(block,loc,i);const active=run.tasks.find(x=>x.start_ns<=t&&t<x.end_ns&&x.operands.includes(block)&&x.trajectory_id);if(active)p=pathPoint(active.trajectory_id,(t-active.start_ns)/(active.end_ns-active.start_ns));const g=node('g',{'data-tip':`${block} · ${loc}`});g.append(node('circle',{cx:p[0],cy:p[1],r:12,fill:active?'#d98b31':'#0d6b59',stroke:'#fff','stroke-width':3}));g.append(node('text',{x:p[0],y:p[1]+4,'text-anchor':'middle',fill:'white','font-size':9,'font-weight':700},block.replace('block-','')));svg.append(g)});bindTips(svg);$('space-meta').textContent=`${s.atoms_present} atoms · ${s.aligned_pair_count} aligned pairs · ${s.known_erasures} erasures`}
function blockPoint(block,loc,index){if(loc.startsWith('in_transit:'))return pathPoint(loc.split(':')[1],.5);const z=run.zones.find(x=>x.zone_id===loc)||run.zones[0],n=parseInt(block.match(/\d+/)?.[0]||index);return [z.x_um+27+(n%2)*45,z.y_um+62+Math.floor(n/2)*24]}
function pathPoint(id,p){const tr=run.trajectories.find(x=>x.trajectory_id===id);if(!tr)return[200,130];const pts=tr.waypoints,lengths=[],total=tr.waypoints.slice(1).reduce((a,x,i)=>{const q=tr.waypoints[i],d=Math.hypot(x[0]-q[0],x[1]-q[1]);lengths.push(d);return a+d},0);let d=Math.max(0,Math.min(1,p))*total;for(let i=0;i<lengths.length;i++){if(d<=lengths[i]){const a=pts[i],b=pts[i+1],f=d/lengths[i];return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}d-=lengths[i]}return pts.at(-1)}
function renderGantt(){const svg=$('gantt');svg.replaceChildren();const lanes=[...new Set(run.tasks.flatMap(x=>x.resources))],left=150,row=27,width=900,height=Math.max(440,lanes.length*row+40);svg.setAttribute('viewBox',`0 0 ${left+width+30} ${height}`);lanes.forEach((lane,i)=>{const y=28+i*row;svg.append(node('line',{x1:left,y1:y+10,x2:left+width,y2:y+10,stroke:'#ebe7dd'}));svg.append(node('text',{x:8,y:y+5,fill:'#526159','font-size':11},lane));run.tasks.filter(x=>x.resources.includes(lane)).forEach(task=>{const x=left+task.start_ns/run.makespan_ns*width,w=Math.max(2,(task.end_ns-task.start_ns)/run.makespan_ns*width),r=node('rect',{x,y:y-10,width:w,height:18,rx:3,fill:colors[task.opcode]||'#777','data-tip':`${task.task_id}\n${task.opcode}\n${fmt(task.start_ns)} → ${fmt(task.end_ns)}${task.wait_ns?'\nwait '+fmt(task.wait_ns)+': '+task.wait_reasons.join(', '):''}`});svg.append(r)})});const x=left+t/run.makespan_ns*width;svg.append(node('line',{x1:x,y1:0,x2:x,y2:height,stroke:'#17211d','stroke-width':2}));bindTips(svg)}
function renderEvents(){const box=$('events');box.replaceChildren();const nearest=run.events.reduce((a,e)=>Math.abs(e.time_ns-t)<Math.abs(a.time_ns-t)?e:a,run.events[0])?.event_id;run.events.forEach(e=>{const row=document.createElement('div');row.className='event'+(e.event_id===nearest?' active':'');row.dataset.id=e.event_id;const kind=e.observation_kind||e.kind;row.innerHTML=`<div class="mono">${fmt(e.time_ns)}</div><div><span class="pill">${escHtml(kind.replaceAll('_',' '))}</span></div><div class="mono">${escHtml(e.task_id)}</div><div>${escHtml(e.opcode)}${e.logical_op_ids.length?' · '+escHtml(e.logical_op_ids.join(', ')):''}${e.observation_id?' · observation '+escHtml(e.observation_id):''}${e.noise_target_id?' · '+escHtml(e.noise_target_id)+' · '+escHtml(e.noise_detail):''}</div>`;box.append(row)});box.querySelector(`[data-id="${CSS.escape(nearest)}"]`)?.scrollIntoView({block:'center'});$('event-meta').textContent=`${run.events.filter(e=>e.time_ns<=t).length} / ${run.events.length} events`}
function bindTips(root){root.querySelectorAll('[data-tip]').forEach(n=>{n.onmousemove=e=>{const tip=$('tip');tip.style.display='block';tip.style.left=e.clientX+12+'px';tip.style.top=e.clientY+12+'px';tip.textContent=n.dataset.tip};n.onmouseleave=()=>$('tip').style.display='none'})}init();
</script></body></html>'''

